import React from 'react';
import styled from 'styled-components';

import Typography from '@dynatrace/strato-design-tokens/typography';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { getTextStyle } from '../../core/utils/styles/text-styles.js';

//#region Typings
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface TitleProps extends WithChildren, StylingProps, DataTestId {}
//#endregion Typings

//#region StyledComponents
const StyledTitle = /* @__PURE__ */ styled.div({
  fontWeight: Typography.Text.Base.Emphasized.Weight,
  ...getTextStyle('base-emphasized'),
});
//#endregion StyledComponents

/** The title of the guided interaction overlays. */
export const Title = (props: TitleProps) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;
  return (
    <StyledTitle
      data-testid={dataTestId}
      className={consumerClassName}
      style={consumerStyle}
    >
      {children}
    </StyledTitle>
  );
};

Title['displayName'] = 'GuidedInteraction.Title';
